(()=>{'use strict';const route=(window.routeCatalog||[]).find(r=>location.pathname.endsWith('/'+r.path));const slot=document.querySelector('[data-ob-route-slot]');if(!route||!slot)return;const byId=new Map(routeCatalog.map(r=>[r.id,r])),chain=[];let item=route;while(item){chain.unshift(item);item=item.parent?byId.get(item.parent):null}slot.replaceChildren();slot.setAttribute('aria-label','Breadcrumb');slot.classList.add('ob-breadcrumb');chain.forEach((r,i)=>{if(i){const sep=document.createElement('span');sep.textContent=' / ';sep.setAttribute('aria-hidden','true');slot.append(sep)}const last=i===chain.length-1,e=document.createElement(last?'span':'button');e.textContent=r.id==='start'?'Omni':r.title;if(last)e.setAttribute('aria-current','page');else e.onclick=async()=>{let ok=false;try{const result=await window.omnibloomHost?.request?.({version:1,id:'route-'+Date.now(),method:'navigation.openBuiltin',params:{routeId:r.id}});ok=result?.ok===true&&result.result?.opened===true}catch(_){}if(!ok){let notice=document.getElementById('ob-route-notice');if(!notice){notice=document.createElement('p');notice.id='ob-route-notice';notice.setAttribute('role','status');slot.after(notice)}notice.textContent='Built-in navigation is unavailable.'}};slot.append(e)});document.title=route.title+' · Omnibloom'})();
